using System;using System.IO;using System.Reflection;using System.Drawing;using System.Windows.Forms;using LoopFive;
class ResearchUiTests {
 static int n;static void A(bool b,string s){if(!b)throw new Exception(s);n++;Console.WriteLine("PASS "+s);}
 static object F(object o,string name){return o.GetType().GetField(name,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).GetValue(o);}
 static EditorGrid Grid(FxPage page){return (EditorGrid)((Panel)F(page,"scroll")).Controls[0];}
 static Control Row(EditorGrid grid,string label){for(int i=0;i<grid.RowCount;i++){Control c=grid.GetControlFromPosition(0,i);if(c!=null&&c.Text==label)return grid.GetControlFromPosition(1,i);}throw new Exception("Missing field "+label);}
 static void Type(FxPage page,string type){((ComboBox)Grid(page).GetControlFromPosition(1,1)).SelectedItem=type;Application.DoEvents();}
 static void Shot(Form f,string name){((FxBar)F(f,"inputBar")).RefreshModel();((FxBar)F(f,"trackBar")).RefreshModel();using(Bitmap b=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(b,new Rectangle(0,0,b.Width,b.Height));b.Save(Path.GetFullPath(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"../../"+name)));}}
 [STAThread]static void Main(){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);string path=Path.Combine(Storage.DataDirectory,"settings.json");byte[] backup=File.Exists(path)?File.ReadAllBytes(path):null;try{using(MainForm f=new MainForm()){f.Opacity=0;f.Show();Application.DoEvents();((Timer)F(f,"timer")).Stop();f.Audio.Stop();f.Engine.System.Language="es";f.Engine.System.UiTheme=Theme.Names[0];f.Engine.System.UiAccent=null;f.ApplyAppearance();f.ApplyLanguage();A(FxKnowledge.Entries.Count==53,"all 53 effect families have bilingual guidance and implementation notes");foreach(string type in FxCatalog.All)A(FxKnowledge.Entries.ContainsKey(type)&&FxKnowledge.Source(type).StartsWith("https://www.jlc.style/"),"effect source and notes present: "+type);f.ShowMainPage(2);FxPage page=(FxPage)F(f,"fxPage");page.SelectSlot(true,0,1);Type(page,"LO-FI");FxConfig c=f.Engine.Config.InputFx.Slots[1];A(c.Detailed,"selecting a new type enables its detailed controls");((NumericUpDown)Row(Grid(page),"Resolución (bits)")).Value=5;((NumericUpDown)Row(Grid(page),"Divisor de muestreo (1 = sin reducción)")).Value=8;A(c.Detail.Bits==5&&c.Detail.SampleDivisor==8,"LO-FI controls update independent bit and sampling settings");A(f.Engine.Config.InputFx.Slots[0].Type=="LPF","editing B leaves A unchanged");Shot(f,"FX-LOFI-2.7.png");Type(page,"VOCODER");((ComboBox)Row(Grid(page),"Portadora del vocoder")).SelectedIndex=3;A(c.Detail.Carrier==3,"VOCODER carrier selector chooses track 4");Shot(f,"FX-Vocoder-2.7.png");((CheckBox)Row(Grid(page),"Controles detallados (modo nuevo)")).Checked=false;Application.DoEvents();A(!c.Detailed&&c.Detail.Carrier==3,"legacy mode retains advanced settings for a reversible switch");((CheckBox)Row(Grid(page),"Controles detallados (modo nuevo)")).Checked=true;Application.DoEvents();A(c.Detailed&&((ComboBox)Row(Grid(page),"Portadora del vocoder")).SelectedIndex==3,"re-enabling detailed mode restores carrier selection");Type(page,"DELAY");((ComboBox)Row(Grid(page),"División musical (activa sincronización)")).SelectedIndex=14;Application.DoEvents();A(c.Sync&&Math.Abs(c.Beats-1f/3)<.00001,"triplet selector enables sync and the correct beat fraction");page.SelectSlot(false,2,3);Type(page,"DELAY");((ComboBox)Row(Grid(page),"Aplicar este efecto a")).SelectedIndex=5;A(f.Engine.Config.TrackFx.Slots[11].Detail.InsertMask==16,"per-slot target control assigns only track 5");page.SelectSlot(true,0,1);Type(page,"LO-FI");f.Engine.System.Language="en";f.ApplyLanguage();A(Row(Grid(page),"Bit depth (bits)") is NumericUpDown&&FxKnowledge.Description("LO-FI").Contains("sample rate"),"new controls and guide descriptions switch to English");f.Engine.Dirty=false;f.Close();}Console.WriteLine("TOTAL "+n+" research UI checks passed");}catch(Exception ex){Console.WriteLine("FAIL "+ex);Environment.ExitCode=1;}finally{if(backup!=null)File.WriteAllBytes(path,backup);else if(File.Exists(path))File.Delete(path);Language.Set("es");}}
}
